/// The encrypted objects of a file.
enum MediaVariant {
  /// 512 px JPEG generated by the device that uploaded it.
  thumbnail,

  /// 2048 px JPEG for the viewer, generated by the device that uploaded it. Only images bigger than 2048 px uploaded
  /// by this version of the app have one (`GalleryFile.hasPreview`).
  preview,

  /// The photo or video as it was on the device.
  original,
}
